"""Migrated invoiced-order workflow, validation, and total recomputation rules."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENTS = Decimal("0.01")


class BusinessRuleViolation(Exception):
    """A legacy business validation failure."""

    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL/numeric-context handling for empty or missing values."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the invoiced-order cancellation workflow transition."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = order.copy()

    if new_status == "I":
        return updated_order, [], []

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        "E5003",
        "Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live line extensions and an unfrozen order total."""
    updated_order = order.copy()
    updated_lines = [line.copy() for line in lines]

    if order.get("STAT_CD") in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        extension = _cents(_numeric(line.get("QTY")) * _numeric(line.get("UNIT_PRC")))
        line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _cents(
        total * (Decimal("100") - _numeric(order.get("DISC_PCT"))) / Decimal("100")
    )

    if _numeric(order.get("TOT_AMT")) != discounted_total:
        updated_order["TOT_AMT"] = float(discounted_total)
        return updated_order, updated_lines, ["ORD_RETOTAL"]

    return updated_order, updated_lines, []
